243	  function handleTabKeydown(event) {
244	    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight' &&
245	      event.key !== 'Home' && event.key !== 'End') {
246	      return;
247	    }
248	
249	    var tab = event.target.closest('[role="tab"]');
