259	
260	    var current = tabs.indexOf(tab);
261	    var nextIndex = current;
262	
263	    if (event.key === 'ArrowRight') {
264	      nextIndex = (current + 1) % tabs.length;
265	    } else if (event.key === 'ArrowLeft') {
266	      nextIndex = (current - 1 + tabs.length) % tabs.length;
267	    } else if (event.key === 'Home') {
268	      nextIndex = 0;
269	    } else if (event.key === 'End') {
270	      nextIndex = tabs.length - 1;
