487	
488	    var text = code.textContent || '';
489	    var copied = false;
490	
491	    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
492	      try {
493	        await navigator.clipboard.writeText(text);
494	        copied = true;
495	      } catch (error) {
496	        copied = false;
497	      }
498	    }
499	
500	    if (!copied) {
501	      copied = fallbackCopy(text);
